import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>画框会改变照片被观看的方式。同一张图片，配细白色边框、拍立得画框或发光渐变边，感觉像是三张不同的照片。</p>\n<p>选样式不只是装饰。画框定下氛围、表明场景，告诉观众这张照片是一段回忆、一件产品，还是一件艺术品。</p>\n<p>这篇文章会对比主要的画框样式和各自最适合的地方。内容包括社交媒体、打印、产品照片、人像，以及让画框看着是特意的颜色与阴影选择。看中哪种样式，<a href=\"/zh/tupian-biankuang-shengcheng/\">图片边框生成器</a>可以直接加上纯色或渐变边框、画框、圆角和阴影。</p>\n<h2 id=\"why-frames-matter\">画框为什么重要</h2>\n<p>画框把图片和周围环境分开。杂乱的页面或拥挤的信息流里，带框的照片能脱颖而出，没有边框的照片可能融进背景。</p>\n<p>画框还给人一种完成感。带边框的照片感觉是成品，像已经装裱好的打印照片；没有边框的照片可能感觉像一个原始文件。</p>\n<p>画框的样式设定了期待。拍立得画框说的是随意回忆，细黑色画框说的是艺术摄影，渐变光晕说的是现代数字设计。</p>\n<p>按想要传达的信息选画框，不只是按外观选。和场景匹配的画框能强化照片，和场景冲突的画框会削弱整张图片。</p>\n<h2 id=\"minimal-frames\">极简画框：少即是多</h2>\n<p>极简画框是一条细细的单色边框，通常是白色或黑色，占图片大小的1%到3%。这是最多才多艺的样式，几乎适合任何照片。</p>\n<p>极简画框好用，是因为它不和图片竞争。眼睛先注意到照片、再注意到画框，这个顺序正好是对的。</p>\n<p>它们最适合专业作品：作品集、产品列表和编辑图片，那里图片应该自己说话，不需要装饰。</p>\n<p>一组照片里保持极简画框一致。同样细边框的一系列照片看着像精心策划的合集，边框混搭则看着随意。</p>\n<h2 id=\"polaroid-and-retro\">拍立得与复古画框</h2>\n<p>拍立得画框模仿即时成像胶片，白色边框，底部有一条更宽的边。感觉怀旧、随意、个人，所以适合度假照片和回忆。</p>\n<p>底部加宽的边带是这种风格的标志。它留出了写手写说明、日期或简短备注的空间，就像真正的拍立得照片一样。</p>\n<p>复古画框最适合随意、个人的照片。正式人像或产品照用它会显得不合时宜，那时干净的极简画框更合适。</p>\n<p>拍立得画框要节制使用。满是拍立得的信息流感觉像主题公园，干净照片里夹一两张，感觉像一段美好的回忆。</p>\n<h2 id=\"gallery-frames\">画廊画框：衬边效果</h2>\n<p>画廊画框是宽宽的白色边框，通常是5%到10%，模仿装裱过的打印照片。它给照片留出呼吸空间，有一种正式、精心策划的感觉。</p>\n<p>画廊画框适合艺术摄影、风景和值得慢慢看的人像。宽衬边让眼睛慢下来，邀请观众仔细研究图片。</p>\n<p>它们最适合打印和作品集。宽边框在小社交信息流预览里浪费空间，所以画廊画框留给大屏展示和打印。</p>\n<p>画廊画框搭配简单中性的背景。衬边应该是唯一的装饰，其他任何东西都会和它竞争。</p>\n<h2 id=\"gradient-and-glow\">渐变与光晕画框</h2>\n<p>渐变光晕画框把颜色混合在图片周围，形成柔和发光的边缘。感觉现代、数字化，适合社交图片、海报和活动公告。</p>\n<p>光晕是根据角度和一组颜色计算出来的。改变角度，光晕混合效果会绕着画框移动，同样的颜色能做出很多不同的样子。</p>\n<p>渐变画框在深色照片上效果很好，明亮的边缘增加了活力。浅色通透的照片用它可能被压住，所以图片需要戏剧感时再用。</p>\n<p>专业场合让光晕保持低调。柔和的渐变增加了精致感，刺眼明亮的光晕会分散观众对照片本身的注意力。</p>\n<h2 id=\"frames-for-social\">社交媒体的画框</h2>\n<p>社交信息流很拥挤，画框能帮照片脱颖而出。白色边框把图片和周围的帖子分开，眼睛会被带框的照片吸引。</p>\n<p>社交画框保持细。厚边框在小信息流预览里占地方，留给照片本身的空间就少了，而照片才是人们来看的东西。</p>\n<p>所有帖子用一致的画框样式。可识别的边框成为视觉形象的一部分，粉丝还没读名字就先认出你的帖子。</p>\n<p>按信息流尺寸测试带框图片。全尺寸看着好的画框，在小预览里可能占主导，发布前先检查。</p>\n<h2 id=\"frames-for-print\">打印的画框</h2>\n<p>打印照片用边框已经有一个多世纪了。打印照片周围的白色边框给人一种画廊感，拿取时也有边距，不会碰到图片。</p>\n<p>打印用5%到10%的中等到宽边框。多出来的空间给打印留出呼吸的余地，也适合人们看打印照片时更慢、更专注的方式。</p>\n<p>加边框之前先检查打印尺寸。边框会增加总尺寸，带框的照片需要的纸张比不带边框的更大。</p>\n<p>装裱打印时，数字边框是设计的一部分。深色画框里的白色边框营造出衬边效果，这是经典的画廊展示方式。</p>\n<h2 id=\"frames-for-products\">产品照片的画框</h2>\n<p>产品照片需要一致的画框，因为边框不一的店铺页面看着很随意。每张产品图片用同样的画框样式和大小。</p>\n<p>细白色边框适合大多数产品。它把商品和页面背景分开，又不分散观众对产品本身的注意力。</p>\n<p>产品照片上不要用彩色画框，除非颜色是品牌的一部分。明亮的画框可能和产品冲突，让商品列表看着不专业。</p>\n<p>促销时彩色画框可以突出优惠。打折产品周围的红色或金色边框能吸引目光，这正是促销的目的。</p>\n<h2 id=\"frames-for-portraits\">人像的画框</h2>\n<p>人像适合简单的画框。细白色或黑色边框让焦点保持在脸上，花哨的画框会和人物抢注意力。</p>\n<p>人像不要用宽边框。大画框让整张图片里的脸变小，削弱观众和主体之间的联系。</p>\n<p>正式人像用黑色画框增加分量。随意人像用白色画框感觉轻松友好，适合家庭和生活方式照片。</p>\n<p>一组人像保持画框一致。边框匹配的一组头像看着像专业合集，边框混搭则看着像意外。</p>\n<h2 id=\"frames-for-screenshots\">截图的画框</h2>\n<p>细白色边框加柔和阴影，能让截图看着像一张卡片。它把屏幕截图和页面分开，看着很精致。</p>\n<p>截图的边框保持细。厚画框会占用截图内容需要的空间，尤其是截图里的文字很小时。</p>\n<p>带框截图导出选PNG。无损格式让小字保持锐利，截图要展示设置或报错信息时，这一点很重要。</p>\n<p>指南或教程里的所有截图用同样的画框样式。一致性能帮助读者跟上步骤，边框混搭会分散读者对说明的注意力。</p>\n<h2 id=\"colour-theory\">画框的颜色理论</h2>\n<p>白色是最安全的画框颜色。任何照片都适合，任何背景上都好用，干净的画廊感永远不会过时。</p>\n<p>黑色增加戏剧性和焦点。适合情绪化的照片、夜景和艺术摄影，浅色画框在这些照片上会显得不合时宜。</p>\n<p>让画框和照片里的某种颜色呼应，能做出设计感。画框取一件衣服、天空或产品的颜色，能把边框和图片联系起来。</p>\n<p>严肃照片上不要用鲜艳饱和的画框。婚礼人像上的霓虹边框看着像个错误，柔和的中性画框看着是特意的。</p>\n<h2 id=\"shadow-and-depth\">阴影与深度</h2>\n<p>阴影给带框图片增加深度，让它看着像浮在页面上方。适合卡片、截图和社交图片。</p>\n<p>阴影在浅色背景上效果最好，深色边缘看得见。深色背景上阴影融进去了，几乎起不到作用。</p>\n<p>想保留阴影，导出选PNG或WebP。JPG没有透明度，阴影在JPG导出里会消失，结果看着很平。</p>\n<p>极简扁平设计完全可以不要阴影。没有深度的干净画框适合编辑作品和作品集，那里简单本身就是重点。</p>\n<h2 id=\"rounded-vs-square\">圆角画框与方角画框</h2>\n<p>方角感觉正式精确。适合产品照片、文件和编辑作品，干净的边缘和内容很搭。</p>\n<p>圆角感觉友好现代。适合社交帖子、卡片和应用图片，柔和的边缘和周围的界面很搭。</p>\n<p>外框圆角控制外侧弧线，照片圆角控制内侧弧线。两个设成同样的值，得到均匀的圆角画框。</p>\n<p>拍立得风格保持方角。经典即时成像的样子是锐利的角，圆角太大就破坏了复古感。</p>\n<h2 id=\"mixing-frame-and-border\">画框与其他编辑的搭配</h2>\n<p>画框常常是编辑的最后一步，而不是第一步。先裁剪照片、调整亮度，再加边框，画框才能和最终图片匹配。</p>\n<p>画框加圆角，做出卡片效果。细边框加柔和圆角，感觉像现代应用卡片，适合社交帖子和演示文稿。</p>\n<p>画框加文字，做出海报。带框图片加顶部标题，就是一张完整的图片，不用再加工就能分享。</p>\n<p>搭配不要过度。画框加浓重滤镜加粗体文字，可能压住照片；一次只做一个强烈的选择，设计才能保持干净。</p>\n<h2 id=\"trends-vs-timeless\">流行与经典画框</h2>\n<p>画框样式和其他东西一样会流行。渐变光晕现在流行，拍立得画框十年前流行，极简白色边框从来没有过时过。</p>\n<p>作品要经得起时间考验时，选经典画框。细白色或黑色边框十年后看着和今天一样好，流行的光晕可能很快就显得过时。</p>\n<p>只活一天的社交帖子，用流行样式没问题。符合当下风格的渐变画框能提升互动，帖子被遗忘的速度比流行褪去的速度快得多。</p>\n<p>拿不准就选极简。简单的画框永远不会错，照片本身能承载图片，而不是装饰。</p>\n<h2 id=\"choosing-cheat-sheet\">选画框速查表</h2>\n<p>社交帖子、产品照片和任何需要干净稳妥画框的内容，用细白色边框。它到处都好用，永远不会错。</p>\n<p>随意回忆、度假照片和个人帖子，用拍立得画框。它感觉怀旧有趣，和内容很搭。</p>\n<p>打印、作品集和艺术摄影，用宽画廊边框。衬边效果给图片留出呼吸空间，有正式感。</p>\n<p>海报、活动图片和社交公告，用渐变光晕。明亮的边缘增加活力，适合要抓注意力内容。</p>\n<h2 id=\"frames-for-events\">活动公告的画框</h2>\n<p>活动公告需要能抓注意力的画框。渐变光晕或大胆的彩色边框，能让海报在满是素照片的信息流里脱颖而出。</p>\n<p>画框和活动氛围匹配。明亮的渐变适合派对或音乐会，干净的黑色边框适合会议或正式晚宴。</p>\n<p>活动细节保持可读。大胆的画框不该遮住日期、地点或票价，文字要放在画框内足够靠里的位置。</p>\n<p>同一活动的所有帖子用同样的画框样式。一致的外观能帮助粉丝在好几条帖子里认出活动，期待感也随之建立。</p>\n<p>分步骤的操作见<a href=\"/zh/blog/ruhe-gei-tupian-jia-biankuang/\">如何给图片加边框</a>，完整概览见<a href=\"/zh/blog/tupian-biankuang-wanquan-zhinan/\">图片边框完全指南</a>。想把带框照片的角变圆，可以用<a href=\"/zh/yuanjiao-tupian/\">图片圆角工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Instagram帖子用哪种画框样式最好？","answer":"细白色边框最稳妥：它把照片和信息流分开，任何图片都适合，永远不会过时。大小保持在1%到3%，小预览里才不占地方。所有帖子用同一风格，信息流才有可识别的外观。"},{"question":"什么时候用拍立得画框？","answer":"随意、个人的照片适合用，比如度假、聚会和回忆，怀旧的即时成像风格和氛围很搭。正式人像或产品照不要用拍立得画框，干净的纯色边框更合适。"},{"question":"渐变光晕画框专业吗？","answer":"用在合适的内容上、保持低调时，可以很专业。柔和的渐变适合海报、活动图片和社交公告。作品集、客户作品或正式照片，用极简白色或黑色边框看着更专业。"},{"question":"打印照片用什么画框样式最好？","answer":"5%到10%的宽白色边框，模仿装裱过的画廊打印照片，给图片留出呼吸空间。先检查纸张尺寸，因为边框会增加总尺寸，照片需要更大的纸张。"},{"question":"所有产品照片都应该用同样的画框吗？","answer":"应该。整个目录保持一致，店铺看着整齐可信；边框混搭看着随意。每张产品图片用一种细白色边框样式，彩色画框只留给促销或特价商品。"},{"question":"圆角适合所有画框样式吗？","answer":"不适合。圆角适合社交帖子、卡片和应用图片，柔和的边缘和界面很搭。方角适合产品照片、文件和正式作品。拍立得画框保持方角，才能保留复古的即时成像感。"}];
